# 3. Inputs
# ----------------------------------------------------------------------
def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Identify all entities that entered the scene at frame 0
    and capture their initial state from the motion log.
    Each input contains: id, time, kind ("arrival"), entities, fields, src.
    """
    nodes = scope_nodes(doc, scope)
    event_node = None
    motion_node = None
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Events"):
            event_node = node
        if node["kind"] == "table" and node["title"].endswith("Motion log"):
            motion_node = node

    # Map object id to description from Objects list
    obj_desc_map: Dict[str, str] = {}
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Objects"):
            for line in node["lines"]:
                m = re.match(r"Object (\d+): (.+?) \(", line)
                if m:
                    obj_desc_map[m.group(1)] = m.group(2).strip()

    # Build a lookup for first motion log row of each object at frame 0
    motion0: Dict[str, Tuple[Dict[str, str], int]] = {}
    if motion_node:
        for row_index, row in table_rows(motion_node):
            if int(row.get("frame", -1)) == 0:
                obj_col = row["object"]
                # object description string like "1 red rubber cube"
                mobj = re.match(r"(\d+)\s+", obj_col)
                if mobj:
                    oid = mobj.group(1)
                    motion0[oid] = (row, row_index)

    inputs: List[Dict[str, Any]] = []
    if event_node:
        for line_index, line in enumerate(event_node["lines"]):
            if "is in view when the video begins." in line:
                # Parse object number
                m = re.search(r"Object (\d+)", line)
                if not m:
                    continue
                oid = m.group(1)
                # Build fields from motion log if available
                row, row_idx = motion0.get(oid, (None, None))
                fields: Dict[str, Union[float, str]] = {"time": 0.0}
                if row:
                    for key in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[key] = float(row[key])
                        except Exception:
                            fields[key] = row[key]
                inp_id = f"in_{oid}"
                src = [[event_node["node_id"], line_index]]
                if row:
                    src[0].append([row_idx])  # indicate table row
                inputs.append({
                    "id": inp_id,
                    "time": 0.0,
                    "kind": "arrival",
                    "entities": [oid],
                    "fields": fields,
                    "src": src
                })

    return inputs


# ----------------------------------------------------------------------
# 4. Outcomes
# ----------------------------------------------------------------------
def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return a list of events that are results of the physical process:
    collisions and exits from view.
    """
    nodes = scope_nodes(doc, scope)
    event_node = None
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Events"):
            event_node = node

    outcomes: List[Dict[str, Any]] = []
    if not event_node:
        return outcomes

    for line_index, line in enumerate(event_node["lines"]):
        # Skip the initial "in view" lines (these are inputs)
        if "is in view when the video begins." in line:
            continue

        m = re.match(r"Frame (\d+): Object (\d+) (collides with Object (\d+)|exits view)", line)
        if not m:
            continue
        frame = int(m.group(1))
        oid1 = m.group(2)
        kind_str = m.group(3)
        if kind_str.startswith("collides"):
            oid2 = m.group(4)
            kind = "collision"
            ents = [oid1, oid2]
        else:
            kind = "exit"
            ents = [oid1]
        outcomes.append({
            "time": float(frame),
            "kind": kind,
            "entities": ents,
            "value": None,
            "src": [[event_node["node_id"], line_index]]
        })
    return outcomes


