import re
from typing import Any, Dict, List, Tuple, Set

# ----------------------------------------------------------------------
# Helpers assumed to be available in environment
# ----------------------------------------------------------------------
# node_by_title(doc, title)           -> node dict
# node_by_id(doc, node_id)            -> node dict
# children(doc, node)                 -> list of node dicts
# scope_nodes(doc, scope)             -> list of child nodes of scope
# table_rows(node) -> [(row_index, {column: cell})]
# ----------------------------------------------------------------------


# ----------------------------------------------------------------------
# 1. Entities
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return all distinct entities in the scope.
    Each entity gets a string id (as in "0") and a human‑readable description.
    """
    nodes = scope_nodes(doc, scope)
    desc: Dict[str, str] = {}
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Objects"):
            for line in node["lines"]:
                m = re.match(r"Object (\d+):\s+([^()]+)", line)
                if m:
                    oid, d = m.groups()
                    desc[oid] = d.strip()
    # if no objects line present, try to collect from motion log?
    if not desc:
        for node in nodes:
            if node["kind"] == "table" and node["title"].endswith("Motion log"):
                for _, row in table_rows(node):
                    oid = row.get("object", "")
                    # object cell like "1 red rubber cube" – pick first token
                    oid = oid.split()[0]
                    if oid.isdigit() and oid not in desc:
                        desc[oid] = f"{oid}"
    return [{"id": k, "description": desc[k]} for k in sorted(desc, key=int)]


# ----------------------------------------------------------------------
# 2. Recorded end
# ----------------------------------------------------------------------
def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """
    Last frame number in the motion log.
    """
    nodes = scope_nodes(doc, scope)
    last: int | None = None
    for node in nodes:
        if node["kind"] == "table" and node["title"].endswith("Motion log"):
            for _, row in table_rows(node):
                try:
                    f = int(row.get("frame", -1))
                except Exception:
                    continue
                if f < 0:
                    continue
                if last is None or f > last:
                    last = f
    return float(last) if last is not None else None


# ----------------------------------------------------------------------
# 3. Inputs
# ----------------------------------------------------------------------
def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Capture:
      * Object definitions (one per entry in the Objects list)
      * Object arrivals (view starts or explicit 'enters')
    """
    nodes = scope_nodes(doc, scope)
    inp: List[Dict[str, Any]] = []

    # Build maps from node id for easier src creation
    node_map = {n["node_id"]: n for n in nodes}

    # 3.1 Objects definitions
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Objects"):
            for idx, line in enumerate(node["lines"]):
                m = re.match(r"Object (\d+):\s+([^()]+)", line)
                if not m:
                    continue
                oid, desc = m.groups()
                inp_id = f"def_{oid}"
                inp.append({
                    "id": inp_id,
                    "time": None,
                    "kind": "definition",
                    "entities": [oid],
                    "fields": {"description": desc.strip()},
                    "src": [[node["node_id"], idx]],
                })

    # 3.2 Arrival events
    # For each event line that indicates an object is in view at frame 0 or later'
    event_node = None
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Events"):
            event_node = node
            break
    motion_node = None
    for node in nodes:
        if node["kind"] == "table" and node["title"].endswith("Motion log"):
            motion_node = node
            break

    if event_node:
        for lidx, line in enumerate(event_node["lines"]):
            # frame 0 view start
            if "is in view when the video begins." in line:
                frame = 0
            else:
                m = re.match(r"Frame (\d+): Object (\d+) .* enters", line)
                if not m:
                    continue
                frame = int(m.group(1))
            objid = re.search(r"Object (\d+)", line)
            if not objid:
                continue
            oid = objid.group(1)
            # Build fields
            fields: Dict[str, Any] = {"time": float(frame)}
            src = [[event_node["node_id"], lidx]]
            if motion_node:
                # find first log row for this object at same frame
                for ridx, row in table_rows(motion_node):
                    try:
                        if int(row["frame"]) == frame and row["object"].startswith(oid):
                            for key in ("x", "y", "vx", "vy", "speed"):
                                try:
                                    fields[key] = float(row[key])
                                except Exception:
                                    fields[key] = row[key]
                            src.append([motion_node["node_id"], ridx])
                            break
                    except Exception:
                        continue
            inp_id = f"arr_{oid}_{frame}"
            inp.append({
                "id": inp_id,
                "time": float(frame),
                "kind": "arrival",
                "entities": [oid],
                "fields": fields,
                "src": src,
            })

    return inp


# ----------------------------------------------------------------------
# 4. Outcomes
# ----------------------------------------------------------------------
def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Events that are results of the process:
      * collisions
      * exits from view
    Each outcome records its source line(s).
    """
    nodes = scope_nodes(doc, scope)
    out: List[Dict[str, Any]] = []

    event_node = None
    for node in nodes:
        if node["kind"] == "list" and node["title"].endswith("Events"):
            event_node = node
            break

    if not event_node:
        return out

    for lidx, line in enumerate(event_node["lines"]):
        # Collision
        m = re.match(r"Frame (\d+): Object (\d+) collides with Object (\d+)", line)
        if m:
            frame, o1, o2 = m.groups()
            out.append({
                "time": float(frame),
                "kind": "collision",
                "entities": [o1, o2],
                "value": None,
                "src": [[event_node["node_id"], lidx]],
            })
            continue
        # Exit
        m = re.match(r"Frame (\d+): Object (\d+) exits view", line)
        if m:
            frame, oid = m.groups()
            out.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [oid],
                "value": None,
                "src": [[event_node["node_id"], lidx]],
            })
            continue

    return out


# ----------------------------------------------------------------------
# 5. Params
# ----------------------------------------------------------------------
def params(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    """
    The document contains no explicit constants.  Return empty dict.
    """
    return {}
